import{_ as t,o as s,c as e,a2 as n}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 15 章 自动化工作流：让任务自己跑","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 15 章 自动化工作流：让任务自己跑.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 15 章 自动化工作流：让任务自己跑.md"}'),o={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 15 章 自动化工作流：让任务自己跑.md"};function l(i,a,d,p,r,h){return s(),e("div",null,[...a[0]||(a[0]=[n(`<div class="tip custom-block"><p class="custom-block-title">🎈 想读易懂版？</p><p>本章有<strong>易懂版</strong>（大白话讲重点，10 分钟读完）：[第 15 章 自动化工作流：让任务自己跑（易懂版）](../../easy/第15章 自动化工作流：让任务自己跑（易懂版）.md)</p></div><h1 id="第-15-章-自动化工作流-让任务自己跑" tabindex="-1">第 15 章 自动化工作流：让任务自己跑 <a class="header-anchor" href="#第-15-章-自动化工作流-让任务自己跑" aria-label="Permalink to &quot;第 15 章 自动化工作流：让任务自己跑&quot;">​</a></h1><blockquote><p>本章目标：理解自动化的适用场景、三层境界与可靠性的三要素，掌握自动化与 Skill 的分工。<strong>自动化的目的不是去掉人，而是把人从重复劳动里解放出来，去做判断。</strong></p></blockquote><h2 id="_15-1-场景-有些事你已经会做了-只是不想每次重做" tabindex="-1">15.1 场景：有些事你已经会做了，只是不想每次重做 <a class="header-anchor" href="#_15-1-场景-有些事你已经会做了-只是不想每次重做" aria-label="Permalink to &quot;15.1 场景：有些事你已经会做了，只是不想每次重做&quot;">​</a></h2><p>有些任务，你已经知道完整的做法，只是不想每次都手动做一遍。这就是自动化该上场的时候：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入（文件/参数）→ 固定步骤 → 输出（产物/结果）</span></span></code></pre></div><p>自动化的本质：<strong>把&quot;你会做&quot;变成&quot;它会自己跑&quot;。</strong></p><h2 id="_15-2-什么样的任务适合自动化" tabindex="-1">15.2 什么样的任务适合自动化 <a class="header-anchor" href="#_15-2-什么样的任务适合自动化" aria-label="Permalink to &quot;15.2 什么样的任务适合自动化&quot;">​</a></h2><h3 id="_15-2-1-判断表格" tabindex="-1">15.2.1 判断表格 <a class="header-anchor" href="#_15-2-1-判断表格" aria-label="Permalink to &quot;15.2.1 判断表格&quot;">​</a></h3><table tabindex="0"><thead><tr><th>适合</th><th>不适合</th></tr></thead><tbody><tr><td>步骤固定、重复执行</td><td>每次需求都不同</td></tr><tr><td>输入输出明确</td><td>需要大量即兴判断</td></tr><tr><td>有明确验收标准</td><td>高风险不可逆操作</td></tr><tr><td>频率高（每周/每天）</td><td>一次性任务</td></tr></tbody></table><h3 id="_15-2-2-一句话判断" tabindex="-1">15.2.2 一句话判断 <a class="header-anchor" href="#_15-2-2-一句话判断" aria-label="Permalink to &quot;15.2.2 一句话判断&quot;">​</a></h3><blockquote><p><strong>&quot;如果这个任务做 10 遍，步骤会一样吗？&quot;</strong> 会 → 值得自动化；不会 → 先别急。</p></blockquote><h2 id="_15-3-自动化的三层境界" tabindex="-1">15.3 自动化的三层境界 <a class="header-anchor" href="#_15-3-自动化的三层境界" aria-label="Permalink to &quot;15.3 自动化的三层境界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>说明</th><th>例子</th></tr></thead><tbody><tr><td><strong>L1 脚本化</strong></td><td>固定输入 → 脚本 → 固定输出</td><td>批量重命名脚本</td></tr><tr><td><strong>L2 模板化</strong></td><td>用模板生成不同产物</td><td>周报、合同、简报</td></tr><tr><td><strong>L3 工作流化</strong></td><td>多步骤串联 + 异常处理 + 人审节点</td><td>发布会自动化流程</td></tr></tbody></table><h3 id="_15-3-1-三层递进" tabindex="-1">15.3.1 三层递进 <a class="header-anchor" href="#_15-3-1-三层递进" aria-label="Permalink to &quot;15.3.1 三层递进&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L1 解决&quot;一次做一件事&quot;（脚本）</span></span>
<span class="line"><span>L2 解决&quot;每次产出不一样但结构一样&quot;（模板）</span></span>
<span class="line"><span>L3 解决&quot;整条链路都要自动&quot;（工作流）</span></span></code></pre></div><p><strong>大多数自动化做到 L2 就够用了</strong>，别一上来就追求 L3 的完美流水线。</p><h2 id="_15-4-案例-周报自动化" tabindex="-1">15.4 案例：周报自动化 <a class="header-anchor" href="#_15-4-案例-周报自动化" aria-label="Permalink to &quot;15.4 案例：周报自动化&quot;">​</a></h2><p><strong>手动版：</strong> 每周五收集数据 → 写周报 → 发送。</p><p><strong>自动化版：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入：本周 git 提交记录 + 项目进度文件</span></span>
<span class="line"><span>步骤：收集 → 按模板生成周报草稿 → 输出到 docs/weekly/</span></span>
<span class="line"><span>人工节点：你审阅 → 确认 → 发布</span></span></code></pre></div><p><strong>指令：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把&quot;生成周报&quot;做成可复用流程：我每次只说&quot;生成本周周报&quot;，</span></span>
<span class="line"><span>你就走：读 git log → 读进度文件 → 套模板 → 输出草稿让我审阅。</span></span></code></pre></div><h3 id="_15-4-1-自动化的投入产出计算" tabindex="-1">15.4.1 自动化的投入产出计算 <a class="header-anchor" href="#_15-4-1-自动化的投入产出计算" aria-label="Permalink to &quot;15.4.1 自动化的投入产出计算&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>投入：一次（把流程定下来 + 写好模板）</span></span>
<span class="line"><span>产出：每周省 30 分钟 × 52 周 = 26 小时/年</span></span>
<span class="line"><span>结论：只要重复 ≥ 5 次，自动化就回本</span></span></code></pre></div><h2 id="_15-5-可靠性的三要素" tabindex="-1">15.5 可靠性的三要素 <a class="header-anchor" href="#_15-5-可靠性的三要素" aria-label="Permalink to &quot;15.5 可靠性的三要素&quot;">​</a></h2><p>自动化最怕&quot;悄悄出错&quot;。三条保命原则：</p><h3 id="_15-5-1-留痕" tabindex="-1">15.5.1 留痕 <a class="header-anchor" href="#_15-5-1-留痕" aria-label="Permalink to &quot;15.5.1 留痕&quot;">​</a></h3><p>每次运行都有日志，出问题能回看：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>运行时间、输入参数、处理了哪些文件、结果如何 → 都写进运行日志</span></span></code></pre></div><h3 id="_15-5-2-可验证" tabindex="-1">15.5.2 可验证 <a class="header-anchor" href="#_15-5-2-可验证" aria-label="Permalink to &quot;15.5.2 可验证&quot;">​</a></h3><p>产出有校验（行数、格式、内容检查）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;周报生成后，自动检查：标题是否齐全、是否有本周日期、段落是否为空&quot;</span></span></code></pre></div><h3 id="_15-5-3-人审节点" tabindex="-1">15.5.3 人审节点 <a class="header-anchor" href="#_15-5-3-人审节点" aria-label="Permalink to &quot;15.5.3 人审节点&quot;">​</a></h3><p>重要输出在自动化的最后一站，<strong>永远留一个人确认</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>自动生成草稿 → 你确认 → 才发布</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">自动化的核心原则</p><p><strong>自动化 = 把重复交给机器 + 把判断留给人。</strong> 任何&quot;自动化直接发布&quot;的设计，都是在埋雷。</p></div><h2 id="_15-6-自动化与-skill-的区别" tabindex="-1">15.6 自动化与 Skill 的区别 <a class="header-anchor" href="#_15-6-自动化与-skill-的区别" aria-label="Permalink to &quot;15.6 自动化与 Skill 的区别&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skill   = 按最佳实践执行一件事（我来做，你在场）</span></span>
<span class="line"><span>自动化  = 固定流程自己跑（我主动跑，你抽查）</span></span></code></pre></div><h3 id="_15-6-1-两者的结合" tabindex="-1">15.6.1 两者的结合 <a class="header-anchor" href="#_15-6-1-两者的结合" aria-label="Permalink to &quot;15.6.1 两者的结合&quot;">​</a></h3><p><strong>Skill 定义&quot;怎么做对&quot;，自动化定义&quot;什么时候做&quot;。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skill（怎么做对）：写周报的格式规范、数据口径</span></span>
<span class="line"><span>自动化（什么时候做）：每周五自动触发，套用写周报 Skill</span></span></code></pre></div><p><strong>推荐路径：先把&quot;怎么做对&quot;沉淀成 Skill（第 17 章），再让自动化定期调用它。</strong></p><h2 id="_15-7-自动化的进阶-与记忆和团队配合" tabindex="-1">15.7 自动化的进阶：与记忆和团队配合 <a class="header-anchor" href="#_15-7-自动化的进阶-与记忆和团队配合" aria-label="Permalink to &quot;15.7 自动化的进阶：与记忆和团队配合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配合</th><th>用法</th></tr></thead><tbody><tr><td>自动化 + 记忆</td><td>自动读取记忆里的偏好，输出更贴合</td></tr><tr><td>自动化 + 团队</td><td>触发团队协作流程（大任务自动化分派）</td></tr><tr><td>自动化 + 任务库</td><td>把常用流程存成&quot;可调用任务&quot;</td></tr></tbody></table><h2 id="_15-8-练习" tabindex="-1">15.8 练习 <a class="header-anchor" href="#_15-8-练习" aria-label="Permalink to &quot;15.8 练习&quot;">​</a></h2><ol><li>找出你工作中一个每周都要做的重复任务；</li><li>把它的步骤写成清单，让我评估能否自动化（15.2 判断表）；</li><li>实现第一版，跑一次，记录运行日志和人工审阅点；</li><li>用 15.5 的三要素检查：留痕了吗？可验证吗？有人审节点吗？</li></ol><h2 id="_15-9-延伸阅读" tabindex="-1">15.9 延伸阅读 <a class="header-anchor" href="#_15-9-延伸阅读" aria-label="Permalink to &quot;15.9 延伸阅读&quot;">​</a></h2><p>平台把&quot;定时触发&quot;做成了一等公民：<strong>定时任务</strong>（cron）。建任务的规矩、避坑写法、以及怎么把结果直接送到你手机上，见<a href="./../第五篇 平台能力全景/第 28 章 扩展、定时任务与多端接入.html">第 28 章</a>。</p><hr><blockquote><p>小结：自动化的投入产出比，在于<strong>把一次成功变成无数次成功</strong>。但你永远保留最后一公里的人工确认——<strong>自动化不是去掉人，而是解放人。</strong> 下一章，从个人走向团队协作。</p></blockquote>`,51)])])}const b=t(o,[["render",l]]);export{u as __pageData,b as default};
